import { initializeApp } from 'firebase/app';
import { getAuth, connectAuthEmulator } from 'firebase/auth';
import { getFirestore, connectFirestoreEmulator } from 'firebase/firestore';
import { getFunctions, connectFunctionsEmulator } from 'firebase/functions';

const firebaseConfig = {
  apiKey: "AIzaSyCF-AHAcT4hPsII0BJRPpsBGHJJhLCuU2U",
  authDomain: "ndu-bill-payment.firebaseapp.com",
  projectId: "ndu-bill-payment",
  storageBucket: "ndu-bill-payment.firebasestorage.app",
  messagingSenderId: "378264715271",
  appId: "1:378264715271:web:8fab51da1da97e14b06aa2",
  measurementId: "G-ZENWM2XCR9"
};

// Debug: expose the apiKey at runtime to verify what's loaded in the browser
if (typeof window !== 'undefined') {
  // Intentionally log a masked version
  const masked = firebaseConfig.apiKey?.replace(/(.{6}).+(.{4})/, '$1**********$2');
  console.log('[NDU] Firebase apiKey (masked):', masked);
  window.__NDU_FIREBASE_KEY__ = masked;
}

// Initialize Firebase
const app = initializeApp(firebaseConfig);

// Initialize Firebase services
export const auth = getAuth(app);
export const db = getFirestore(app);
export const functions = getFunctions(app);

// Connect to emulators in development
if (process.env.NODE_ENV === 'development') {
  try {
    connectAuthEmulator(auth, 'http://localhost:9099');
    connectFirestoreEmulator(db, 'localhost', 8080);
    connectFunctionsEmulator(functions, 'localhost', 5001);
    console.log('Connected to Firebase emulators');
  } catch (error) {
    console.log('Emulators already connected or not available');
  }
}

export default app;
